import json, re, pathlib
asset_dir = pathlib.Path('tasks/t0078_bedb_mobo_v2_ais_tiered_ahp/assets/paper/10.1016_j.neuron.2022.04.012')
details = json.loads((asset_dir / 'details.json').read_text(encoding='utf-8'))
summary = (asset_dir / 'summary.md').read_text(encoding='utf-8')

errors, warnings = [], []

# ---- details.json checks ----
required = ['spec_version','paper_id','doi','title','url','pdf_url','date_published','year',
            'authors','institutions','journal','venue_type','categories','abstract',
            'citation_key','summary_path','files','download_status','download_failure_reason',
            'added_by_task','date_added']
for k in required:
    if k not in details:
        errors.append(f'PA-E005 missing field: {k}')

if details.get('paper_id') != asset_dir.name:
    errors.append('PA-E004 paper_id mismatch with folder')
if details.get('venue_type') not in ['journal','conference','workshop','preprint','book','thesis','technical_report','other']:
    errors.append('PA-E010 venue_type invalid')
if details.get('download_status') not in ['success','failed']:
    errors.append('PA-E015 invalid download_status')
if details.get('download_status') == 'failed' and not details.get('download_failure_reason'):
    errors.append('PA-E014 missing failure reason')
if details.get('download_status') == 'failed':
    fdir = asset_dir / 'files'
    if not (fdir / '.gitkeep').exists():
        errors.append('files/.gitkeep missing for failed download')

# ---- summary checks ----
if not summary.startswith('---'):
    errors.append('PA-E012 missing frontmatter')

# Frontmatter consistency
fm = summary.split('---', 2)[1]
if 'paper_id: "10.1016_j.neuron.2022.04.012"' not in fm:
    errors.append('PA-E007 paper_id frontmatter mismatch')
if 'citation_key: "Wienbar2022"' not in fm:
    errors.append('PA-E006 citation_key mismatch')
if 'spec_version: "3"' not in fm:
    errors.append('PA-E013 spec_version missing in summary')

# Mandatory sections in order
mandatory = ['## Metadata','## Abstract','## Overview','## Architecture, Models and Methods',
             '## Results','## Innovations','## Datasets','## Main Ideas','## Summary']
last_pos = -1
for sec in mandatory:
    pos = summary.find(sec)
    if pos < 0:
        errors.append(f'PA-E009 missing section: {sec}')
    elif pos < last_pos:
        errors.append(f'sections out of order: {sec}')
    else:
        last_pos = pos

# Word count
words = len(summary.split())
if words < 500:
    warnings.append(f'PA-W001 summary under 500 words: {words}')

# Results bullets
results_block = summary.split('## Results',1)[1].split('## Innovations',1)[0]
results_bullets = len([l for l in results_block.splitlines() if l.startswith('* ')])
if results_bullets < 5:
    warnings.append(f'PA-W002 fewer than 5 bullets in Results: {results_bullets}')

# Main Ideas bullets
mi_block = summary.split('## Main Ideas',1)[1].split('## Summary',1)[0]
mi_bullets = len([l for l in mi_block.splitlines() if l.startswith('* ')])
if mi_bullets < 3:
    warnings.append(f'PA-W003 fewer than 3 bullets in Main Ideas: {mi_bullets}')

# Summary 4 paragraphs
s_block = summary.split('## Summary',1)[1].strip()
paras = [p for p in s_block.split('\n\n') if p.strip()]
if len(paras) != 4:
    warnings.append(f'PA-W004 Summary not exactly 4 paragraphs: {len(paras)}')

# 100-char limit (excluding URLs and table rows)
overlong = []
for i, line in enumerate(summary.splitlines(), 1):
    if len(line) > 100 and not line.lstrip().startswith('|') and 'http' not in line:
        overlong.append((i, len(line)))
if overlong:
    warnings.append(f'lines over 100 chars: {overlong[:3]}')

# Bullet style
if re.search(r'^\s*-\s+', summary, re.MULTILINE):
    errors.append('uses - bullets instead of *')

print('=== ERRORS ===')
for e in errors:
    print(' ', e)
print('=== WARNINGS ===')
for w in warnings:
    print(' ', w)
print(f'words={words} results_bullets={results_bullets} main_ideas_bullets={mi_bullets} summary_paragraphs={len(paras)}')
print('PASS' if not errors else 'FAIL')
